command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: HERZSCHLAG (Zerzal)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (typeof DSK === "undefined" || !globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.1tBOnhW6okOKlMd4");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }

    if (typeof DSK === "undefined" && !globalThis.DSK) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");
    }
    const DSK_FW = globalThis.DSK || DSK; 

    // --- 2. AKTEUR PRÜFEN ---
    const targetActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!targetActor) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Nurtikind!");
    }

    // --- 3. QS & MATHE ERMITTELN ---
    let qsWert = targetActor.getFlag("world", "letzteGabenQS") || 1;
    if (targetActor.getFlag("world", "letzteGabenQS")) {
        await targetActor.unsetFlag("world", "letzteGabenQS"); 
    }

    if (typeof testData !== "undefined" && testData) {
        qsWert = Number(testData?.result?.QL || testData?.qualityStep || qsWert);
    }

    const ahne = "Zerzal";
    const basisName = "Herzschlag";
    const symbolPfad = DSK_FW.Symbol(ahne);

    const radiusMeter = qsWert * 5;
    const dauerMinuten = qsWert; // Dauer laut Gabe: QS Minuten

    const casterToken = canvas.tokens.placeables.find(t => t.actor === targetActor) || canvas.tokens.controlled[0];
    if (!casterToken) {
        return ui.notifications.warn("Kein aktives Token gefunden.");
    }

    const casterName = targetActor.name;
    const finalEffektName = `${basisName} (${ahne})`;
    const abschlussText = "Das Pochen in deinen Ohren verstummt. Du spürst die Herzschläge in deiner Umgebung nicht mehr.";

    // Wirkungsende registrieren
    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("herzschlagZerzal", finalEffektName, abschlussText);
    }

    // --- 4. ZIELE BEIM START AUSLESEN (FLÜSTER-EMPFÄNGER) ---
    // Nur der Spielleiter und der Besitzer des Charakters dürfen das Radar sehen
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    Object.entries(targetActor.ownership || targetActor.permission || {})
        .filter(([id, lvl]) => lvl === 3 && id !== "default")
        .forEach(([id]) => ownerIds.add(id));
    let whisperTargets = Array.from(ownerIds).filter(id => game.users.get(id));

    // --- 5. EFFEKT AUF DEN WIRKENDEN ANLEGEN ---
    const descCaster = `Das Zerzalkind spürt den Herzschlag aller Lebewesen in einem Umkreis von ${radiusMeter} Schritt und kann ungefähr Richtung und Entfernung einschätzen.`;

    for (let ef of targetActor.effects) {
        if ((ef.name || ef.label) === finalEffektName) await ef.delete();
    }

    await DSK_FW.Effekt.Anwenden({
        name: finalEffektName,
        ahne: ahne,
        beschreibung: descCaster,
        gabeZiel: "erwachte", 
        qs: qsWert,
        ziel: targetActor
    });

    // --- 6. LIVE-RADAR LOGIK ---
    globalThis.herzschlagRadar = globalThis.herzschlagRadar || {};
    if (globalThis.herzschlagRadar[targetActor.id]?.hookUpdate) {
        Hooks.off("updateToken", globalThis.herzschlagRadar[targetActor.id].hookUpdate);
    }
    globalThis.herzschlagRadar[targetActor.id] = { letzteMsgId: null, timer: null };

    async function updateRadar() {
        // WICHTIG: Nur der aktive GM führt die Updates durch, das verhindert Fehler bei Spieler-Tokens!
        const activeGM = game.users.find(u => u.isGM && u.active);
        const isUpdater = activeGM ? (game.user.id === activeGM.id) : true;
        if (!isUpdater) return;

        // Prüfen, ob der Effekt noch aktiv ist
        if (!targetActor.effects.find(e => (e.name || e.label) === finalEffektName)) {
            Hooks.off("updateToken", globalThis.herzschlagRadar[targetActor.id]?.hookUpdate);
            return;
        }

        const activeCasterToken = canvas.tokens.get(casterToken.id);
        if (!activeCasterToken) return;

        const radiusPx = (radiusMeter / canvas.scene.grid.distance) * canvas.scene.grid.size;

        // LEBENDE Ziele filtern
        let lebendeZiele = canvas.tokens.placeables.filter(t => {
            if (t.id === activeCasterToken.id) return false;
            if (!t.actor) return false;

            // Untote und unbelebte Konstrukte ausschließen
            const actorType = (t.actor.type || "").toLowerCase();
            const species = (t.actor.system?.species?.value || t.actor.system?.details?.species || "").toLowerCase();
            const excludedWords = ["untot", "geist", "vampir", "leiche", "golem", "skelett", "zombie", "dämon"];

            const isExcluded = excludedWords.some(w => species.includes(w)) || actorType === "spirit";
            if (isExcluded) return false;

            // Distanz check
            const distPx = Math.hypot(t.center.x - activeCasterToken.center.x, t.center.y - activeCasterToken.center.y);
            return distPx <= radiusPx;
        });

        // Informationen für das Radar aufbereiten
        const zielInfos = lebendeZiele.map(t => {
            const dx = activeCasterToken.center.x - t.center.x;
            const dy = activeCasterToken.center.y - t.center.y;
            const distPx = Math.hypot(dx, dy);
            const distSchritt = Math.round((distPx / canvas.scene.grid.size) * canvas.scene.grid.distance);

            let deg = Math.atan2(dy, dx) * (180 / Math.PI);
            if (deg < 0) deg += 360;

            const richtungen = ["Osten", "Nordosten", "Norden", "Nordwesten", "Westen", "Südwesten", "Süden", "Südosten"];
            const richtung = richtungen[Math.round(deg / 45) % 8];

            return `• Herzschlag ca. <b>${distSchritt} Schritt</b> entfernt im <b>${richtung}</b> <i>(${t.name})</i>`;
        });

        const radarHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(`${basisName} (Wahrnehmung)`, symbolPfad)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="font-size:0.95em; margin-bottom: 5px;">
                        <b>${casterName}</b> lauscht auf die Herzschläge in der Umgebung (Radius: ${radiusMeter} Schritt):
                    </p>
                    <div style="background: rgba(139, 0, 0, 0.05); padding: 8px; border-left: 3px solid #8b0000; border-radius: 3px; font-size: 0.9em; line-height: 1.4;">
                        ${zielInfos.length > 0 ? zielInfos.join("<br>") : "<i>Kein Herzschlag in Reichweite zu hören...</i>"}
                    </div>
                    <hr>
                    <p style="text-align:center; font-weight:bold; margin-top:8px;">
                        Wirkungsdauer: ${dauerMinuten} Minuten (QS ${qsWert})
                    </p>
                </div>
            </div>`;

        const radarData = globalThis.herzschlagRadar[targetActor.id];
        if (!radarData) return;

        const msg = game.messages.get(radarData.letzteMsgId);
        if (msg) {
            await msg.update({ content: radarHtml });
        } else {
            const newMsg = await ChatMessage.create({
                content: radarHtml,
                whisper: whisperTargets,
                speaker: { alias: "System" }
            });
            radarData.letzteMsgId = newMsg.id;
        }
    }

    // Radar an den Token-Update binden
    globalThis.herzschlagRadar[targetActor.id].hookUpdate = Hooks.on("updateToken", (doc, change) => {
        if (change.x !== undefined || change.y !== undefined) {
            clearTimeout(globalThis.herzschlagRadar[targetActor.id].timer);
            globalThis.herzschlagRadar[targetActor.id].timer = setTimeout(() => { updateRadar(); }, 500);
        }
    });

    // Initial das Radar einmal starten
    updateRadar();
})();
